param([Parameter(Mandatory=$true)][ValidateSet('ck')][string]$Action)
$ErrorActionPreference='Stop';$ProgressPreference='SilentlyContinue';[Console]::OutputEncoding=[Text.UTF8Encoding]::new($false)
if(-not [Environment]::MachineName.Equals('baiying',[StringComparison]::OrdinalIgnoreCase)){throw 'Requires baiying'}
$repo='D:\projects\AIMA-public-ck-completed-profile-20260914';$source='D:\projects\AIMA-public-partition-product-20260914'
$sha='9bbd5d076c949516afdb80841084b2134f93abc2';$bundle='D:\projects\ck-completed-profile-9bbd5d0.bundle'
if((Get-FileHash $bundle -Algorithm SHA256).Hash.ToLowerInvariant() -ne '1902b5b791299eee12b7678319435caa069b3b197e471ddde16604b156a861b9'){throw 'Bundle changed'}
if(-not (Test-Path $repo)){& git -C $source fetch $bundle HEAD;if($LASTEXITCODE -ne 0){throw 'Fetch failed'};& git -C $source worktree add --detach $repo $sha;if($LASTEXITCODE -ne 0){throw 'Worktree creation failed'}}
if((& git -C $repo rev-parse HEAD).Trim() -ne $sha -or @(& git -C $repo status --porcelain).Count -ne 0){throw 'Source mismatch'}
$specDir=Join-Path $repo 'build\batch-specs';$null=New-Item -ItemType Directory -Path $specDir -Force
$buildName=$Action;$runTag='r1'
$out=Join-Path $repo ('build\'+$buildName);$recordDir=Join-Path $repo ('build\batch-'+$Action+'-build-'+$runTag);$specPath=Join-Path $specDir ($Action+'-build-'+$runTag+'.json')
foreach($p in @($out,$recordDir,$specPath)){if(Test-Path $p){throw ('Existing evidence: '+$p)}}
$env:PATH='C:\Program Files\AMD\ROCm\7.1\bin;'+$env:PATH
$exe='C:\Windows\System32\WindowsPowerShell\v1.0\powershell.exe'
$sourceInputs=@()
$sourceFiles=@(Join-Path $repo 'native\providers\sm121_attention_capacity.h';Join-Path $repo 'scripts\baiying_build_ck_fmha_q8192.ps1')
foreach($folder in @('native\providers\ck_fmha','native\providers\moe_accumulator','native\providers\gdn')){
 $sourceFiles+=@(Get-ChildItem -LiteralPath (Join-Path $repo $folder) -Recurse -File|Where-Object {$_.Extension -in @('.h','.hpp','.cpp')}|ForEach-Object {$_.FullName})
}
foreach($file in @($sourceFiles|Sort-Object -Unique)){
 $sourceInputs+=@{file=$file.Substring($repo.Length+1);sha256=(Get-FileHash $file -Algorithm SHA256).Hash.ToLowerInvariant()}
}
$spec=[ordered]@{executable=$exe;working_directory=$repo;repo_commit=$sha;sm121_dpp_reduction=$true;sm121_compact_normalize=$true;command_file=$PSCommandPath;command_file_sha256=(Get-FileHash $PSCommandPath -Algorithm SHA256).Hash.ToLowerInvariant();model='none; native build and component smoke';model_loaded=$false;inference_acceptance=$false;source_inputs=$sourceInputs;purpose=('Add opt-in completed host phase timings using the existing compact attention observer. Numerical kernels, bounds and default dispatch remain unchanged. Verify native HIP compilation before original q8192/out512 GB10 qualification: '+$Action);exact_attention_maximum_tokens=131072}
switch($Action){
 'ck'{
 $null=New-Item -ItemType Directory -Path $out -Force
 $ck='D:\projects\composable-kernel-fdf4bb7';$dll=Join-Path $out 'qrt_ck_fmha_sm121.dll'
 $headers=@(Get-ChildItem -LiteralPath $ck -Recurse -File|Where-Object {$_.Extension -in @('.h','.hpp','.cpp')}|Sort-Object FullName|ForEach-Object {@{file=$_.FullName.Substring($ck.Length+1);bytes=$_.Length;sha256=(Get-FileHash $_.FullName -Algorithm SHA256).Hash.ToLowerInvariant()}})
 $headerPath=Join-Path $out 'ck-source-inputs.json';[IO.File]::WriteAllText($headerPath,($headers|ConvertTo-Json -Depth 5),[Text.UTF8Encoding]::new($false))

 $spec.sm121_interpolated_exp2=$true;$spec.source_inputs=$sourceInputs;$spec.ck_source_manifest_sha256=(Get-FileHash $headerPath -Algorithm SHA256).Hash.ToLowerInvariant();$spec.ck_source_files=$headers.Count
 $arguments=@('-NoLogo','-NoProfile','-NonInteractive','-File',(Join-Path $repo 'scripts\baiying_build_ck_fmha_q8192.ps1'),'-CkRoot',$ck,'-Sm121InterpolatedExp2','-DppReduction','1','-CompactNormalize','1','-OutPath',$dll,'-HipccPath','C:\Program Files\AMD\ROCm\7.1\bin\hipcc.exe');$timeout=210
 }
}
$spec.arguments=$arguments
[IO.File]::WriteAllText($specPath,($spec|ConvertTo-Json -Depth 8),[Text.UTF8Encoding]::new($false))
& (Join-Path $repo 'scripts\baiying_guarded_inference.ps1') -SpecPath $specPath -OutDir $recordDir -TimeoutSeconds $timeout|Out-Null
$r=[IO.File]::ReadAllText((Join-Path $recordDir 'run-record.json'))|ConvertFrom-Json
$r|Select-Object reason,exit_code,wall_ms,host_checks|ConvertTo-Json -Depth 5
foreach($file in @('product.stdout.jsonl','product.stderr.log')){if(Test-Path (Join-Path $recordDir $file)){Get-Content (Join-Path $recordDir $file) -Tail 4|ForEach-Object {$_.Substring(0,[Math]::Min(800,$_.Length))}}}
if($r.reason -ne 'completed' -or $r.exit_code -ne 0 -or -not $r.host_checks_pass){throw ('Native build failed: '+$Action)}
if($Action -eq 'ck'){
 $meta=[ordered]@{host=[Environment]::MachineName;repo_commit=$sha;sm121_dpp_reduction=$true;sm121_compact_normalize=$true;sm121_interpolated_exp2=$true;source_inputs=$sourceInputs;ck_source_manifest_sha256=$spec.ck_source_manifest_sha256;ck_source_files=$spec.ck_source_files;command_file=$PSCommandPath;run_record_sha256=(Get-FileHash (Join-Path $recordDir 'run-record.json') -Algorithm SHA256).Hash.ToLowerInvariant();artifact=@{file=$dll;bytes=(Get-Item $dll).Length;sha256=(Get-FileHash $dll -Algorithm SHA256).Hash.ToLowerInvariant()}}
 [IO.File]::WriteAllText((Join-Path $out 'build-provenance.json'),($meta|ConvertTo-Json -Depth 8),[Text.UTF8Encoding]::new($false))
}
